kernel_src="""
#include "kernel_operator.h"
constexpr int32_t BUFFER_NUM = 2; // tensor num for each queue

class KernelElu {
public:
    __aicore__ inline KernelElu() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, uint32_t totalLength, uint32_t tileNum, float alpha)
    {
        this->blockLength = totalLength / AscendC::GetBlockNum();
        this->tileNum = tileNum;
        this->alpha = static_cast<float>(alpha);
        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;

        xGm.SetGlobalBuffer((__gm__ float *)x + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
        yGm.SetGlobalBuffer((__gm__ float *)y + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);

        pipe.InitBuffer(inQueueX, BUFFER_NUM, this->tileLength * sizeof(float));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, this->tileLength * sizeof(float));
        pipe.InitBuffer(tmpBufPos, this->tileLength * sizeof(float));  // max(x, 0)
        pipe.InitBuffer(tmpBufNeg, this->tileLength * sizeof(float));  // min(x, 0)
        pipe.InitBuffer(tmpBufExp, this->tileLength * sizeof(float));  // exp(min(x,0)) - 1
    }
    __aicore__ inline void Process()
    {
        int32_t loopCount = this->tileNum * BUFFER_NUM;
        for (int32_t i = 0; i < loopCount; i++) {
            CopyIn(i);
            Compute(i);
            CopyOut(i);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t progress)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], this->tileLength);
        inQueueX.EnQue(xLocal);
    }
    __aicore__ inline void Compute(int32_t /*progress*/)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
        AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();

        AscendC::LocalTensor<float> posLocal = tmpBufPos.Get<float>();
        AscendC::LocalTensor<float> negLocal = tmpBufNeg.Get<float>();
        AscendC::LocalTensor<float> expLocal = tmpBufExp.Get<float>();

        // posLocal = max(x, 0)
        AscendC::Maxs(posLocal, xLocal, 0.0f, this->tileLength);
        // negLocal = min(x, 0)
        AscendC::Mins(negLocal, xLocal, 0.0f, this->tileLength);
        // expLocal = exp(negLocal)
        AscendC::Exp(expLocal, negLocal, this->tileLength);
        // expLocal = exp(negLocal) - 1
        AscendC::Adds(expLocal, expLocal, -1.0f, this->tileLength);
        // expLocal = alpha * (exp(negLocal)-1)
        AscendC::Muls(expLocal, expLocal, this->alpha, this->tileLength);
        // y = posLocal + expLocal
        AscendC::Add(yLocal, posLocal, expLocal, this->tileLength);

        outQueueY.EnQue<float>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }
    __aicore__ inline void CopyOut(int32_t progress)
    {
        AscendC::LocalTensor<float> yLocal = outQueueY.DeQue<float>();
        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, this->tileLength);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> tmpBufPos, tmpBufNeg, tmpBufExp;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::GlobalTensor<float> xGm, yGm;
    uint32_t blockLength;
    uint32_t tileNum;
    uint32_t tileLength;
    float alpha;
};

extern "C" __global__ __aicore__ void elu_custom(GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling) {
    GET_TILING_DATA(tiling_data, tiling);
    KernelElu op;
    op.Init(x, y, tiling_data.totalLength, tiling_data.tileNum, tiling_data.alpha);
    op.Process();
}
